 function translit(word){
   var w=word.toLowerCase(), out='', i=0;
   // word ending -a often becomes ہ in nouns is too risky; keep table result, fix common start
   while(i<w.length){
     var matched=false;
     for(var j=0;j<table.length;j++){ var pat=table[j][0]; if(w.substr(i,pat.length)===pat){ out+=table[j][1]; i+=pat.length; matched=true; break; } }
     if(!matched){ out+=w[i]; i++; }
   }
   // drop standalone alif inserted after initial letter for readability in some cases is left as-is (best effort)
   return out;
 }
 function convertToken(tok){
   var low=tok.toLowerCase();
   if(DICT[low]) return DICT[low];
   return translit(low);
 }
 function update(){
   var text=input.value;
   var tokens=text.split(/(\s+)/); // keep spaces
   var out=[], i=0;
   while(i<tokens.length){
     var tok=tokens[i];
     if(/^\s+$/.test(tok)||tok===''){ out.push(tok); i++; continue; }
     // longest phrase match: try tok + space + next non-space tokens (up to 3 words)
     var found=null, consumed=0;
     var wordsIdx=[];
     // collect up to next 3 word token positions
     var pos=[]; var j=i;
     while(pos.length<3 && j<tokens.length){ if(!/^\s+$/.test(tokens[j])&&tokens[j]!=='') pos.push(j); j++; }
     for(var n=Math.min(3,pos.length); n>=2; n--){
       var phrase=[]; for(var k=0;k<n;k++) phrase.push(tokens[pos[k]].toLowerCase().replace(/[.,!?;:"()]/g,''));
       var key=phrase.join(' ');
       if(DICT[key]){ found=DICT[key]; consumed=n; break; }
     }
     if(found){ out.push(found); // skip tokens up to pos[consumed-1], preserving one space
       var lastPos=pos[consumed-1]; i=lastPos+1; if(i<tokens.length && /^\s+$/.test(tokens[i])){ /* keep space handled next loop or push single */ }
       continue;
     }
     // preserve trailing punctuation outside lookup
     var m=tok.match(/^([A-Za-z']+)([.,!?;:"()]*)$/);
     if(m){ out.push(convertToken(m[1])+m[2]); } else { out.push(convertToken(tok)); }
     i++;
   }
   output.value=out.join('');
 }
 input.addEventListener('input',update);
 document.getElementById('clearBtn').addEventListener('click',function(){input.value='';update();input.focus();});
 document.getElementById('copyBtn').addEventListener('click',function(){ if(output.value&&navigator.clipboard) navigator.clipboard.writeText(output.value); var m=document.getElementById('msg'); m.classList.remove('d-none'); setTimeout(function(){m.classList.add('d-none');},1500); });
 update();
})();
</script>
